"    if(tag!==renderSeq) return;\n"
"    setOnline(true);\n"
"    setNetLabel(s.network&&s.network==='AP'?('AP · '+esc(s.ssid||'')):'STA');\n"
"    main.innerHTML=\n"
"      '<div class=\"section-header\"><h2>WiFi Network Setup</h2></div>'+\n"
"      '<div class=\"card\"><p class=\"entity-meta\">Configure this device to join your local WiFi. After saving it reboots in STA mode (no more AP).</p></div>'+\n"
"      '<div class=\"card\"><h2>Scan Networks</h2>'+\n"
"        '<button class=\"btn btn-primary\" id=\"scanBtn\">Scan for networks</button>'+\n"
"        '<div id=\"scanList\" style=\"margin-top:12px\"></div>'+\n"
"      '</div>'+\n"
"      '<div class=\"card\"><h2>Connect to WiFi</h2>'+\n"
"        '<div class=\"form-row\"><div><label>SSID</label><input id=\"netSsid\" list=\"scanOpts\" placeholder=\"Network name...\"></div>'+\n"
"        '<div><label>Password</label><input id=\"netPassword\" type=\"password\" placeholder=\"Leave empty for open networks\"></div></div>'+\n"
"        '<datalist id=\"scanOpts\"></datalist>'+\n"
"        '<label><input type=\"checkbox\" id=\"netEnable\" checked style=\"width:auto;margin-right:6px\">Enable STA (connect on boot)</label>'+\n"
"        '<div style=\"margin-top:12px\"><button class=\"btn btn-primary\" id=\"connectBtn\">Save & Reboot</button> <span id=\"netMsg\" class=\"empty\"></span></div>'+\n"
"      '</div>';\n"
"    var scanBtn=document.getElementById('scanBtn');\n"
"    var connectBtn=document.getElementById('connectBtn');\n"
"    var msg=document.getElementById('netMsg');\n"
"    var renderScanList=function(nets){\n"
"      var sl=document.getElementById('scanList');\n"
"      if(!nets.length){ sl.innerHTML='<div class=\"empty\">No networks found. Try scanning again.</div>'; return; }\n"
"      sl.innerHTML='<div class=\"empty\" style=\"margin-bottom:6px\">Click an SSID to select it:</div>'+\n"
"        nets.map(function(n){ return '<button class=\"btn btn-ghost\" style=\"width:auto;margin:2px 4px\" data-ssid=\"'+esc(n.ssid)+'\">'+esc(n.ssid)+' ('+esc(n.rssi)+' dBm)</button>'; }).join('');\n"
"      Array.prototype.forEach.call(sl.querySelectorAll('[data-ssid]'),function(b){\n"
"        b.addEventListener('click',function(){ document.getElementById('netSsid').value=b.dataset.ssid; });\n"
"      });\n"
"    };\n"
"    scanBtn.addEventListener('click',function(){\n"
"      msg.textContent='Scanning...';\n"
"      scanBtn.disabled=true;\n"
"      apiFetch('/wifi/scan').then(function(nets){\n"
"        scanCache=nets||[];\n"
"        renderScanList(scanCache);\n"
"        var d=document.getElementById('scanOpts');\n"
"        d.innerHTML=scanCache.map(function(n){ return '<option value=\"'+esc(n.ssid)+'\">'; }).join('');\n"
"        msg.textContent='Found '+scanCache.length+' network(s).';\n"
"        scanBtn.disabled=false;\n"
"      }).catch(function(e){ msg.textContent='Scan failed.'; scanBtn.disabled=false; });\n"
"    });\n"
"    connectBtn.addEventListener('click',function(){\n"
"      var ssid=document.getElementById('netSsid').value.trim();\n"
"      if(!ssid){ msg.textContent='SSID is required.'; return; }\n"
"      var password=document.getElementById('netPassword').value;\n"
"      var enable=document.getElementById('netEnable').checked;\n"
"      msg.textContent='Saving...';\n"
"      connectBtn.disabled=true;\n"
"      apiFetch('/wifi/connect',{method:'POST',body:JSON.stringify({ssid:ssid,password:password,enabled:enable})})\n"
"        .then(function(d){\n"
"          msg.textContent='Saved. Rebooting into STA mode...';\n"
"          setTimeout(function(){ setOnline(false); },500);\n"
"        })\n"
"        .catch(function(e){ msg.textContent='Save failed: '+(e&&e.message?e.message:'error'); connectBtn.disabled=false; });\n"
"    });\n"
"  }).catch(function(e){ if(tag===renderSeq){ setOnline(false); renderError(e); throw e; } });\n"
"}\n"
"\n"
"var RENDERERS={dashboard:renderDashboard,devices:renderDevices,entities:renderEntities,rules:renderRules,skills:renderSkills,logs:renderLogs,system:renderSystem,network:renderNetwork};\n"
"\n"
"/* True while a create/edit form (or the network setup form) owns the main\n"
" * content area. The auto-refresh must not re-render (and thereby wipe) these\n"
" * because they hold live form state (e.g. WiFi scan results, unsaved edits). */\n"
"var inFormView=false;\n"
"/* Tabs whose content is a read-only data view and therefore safe to refresh\n"
" * automatically. \"network\" is intentionally excluded (live form + scan state). */\n"
"var REFRESHABLE={dashboard:1,devices:1,entities:1,rules:1,skills:1,logs:1,system:1};\n"
"\n"
"function renderTab(name){\n"
"  renderSeq++;\n"
"  var tag=renderSeq;\n"
"  inFormView=false;\n"
"  (RENDERERS[name]||renderDashboard)(tag);\n"
"}\n"
"window.loadTab=renderTab;\n"
"\n"
"/* Selective refresh: only re-render data-only tabs, and never clobber an\n"
" * active form view. This avoids gratuitous server calls and heap churn. */\n"
"function refreshVisible(){\n"
"  if(inFormView) return;\n"
"  if(!(cur in REFRESHABLE)) return;\n"
"  renderTab(cur);\n"
"}\n"
"\n"
"window.showCreateRule=function(){\n"
"  inFormView=true;\n"
"  var main=document.getElementById('mainContent');\n"
"  main.innerHTML='<div class=\"card\"><h2>Create Rule</h2><p class=\"entity-meta\">Example: temperature &gt; 30 &rarr; fan ON</p><form id=\"ruleForm\">'+\n"
"    '<div class=\"form-row\"><div><label>Name</label><input name=\"name\" required></div>'+\n"
"    '<div><label>Rule ID (optional, auto-generated)</label><input name=\"rule_id\" placeholder=\"rule-001\"></div></div>'+\n"
"    '<h2 style=\"margin-top:12px\">Trigger</h2>'+\n"
"    '<div class=\"form-row\"><div><label>Device ID</label><input name=\"trg_dev\" value=\"dashboard\" required></div>'+\n"
"    '<div><label>Entity ID</label><input name=\"trg_ent\" value=\"temperature\" required></div></div>'+\n"
"    '<div class=\"form-row\"><div><label>Operator</label><select name=\"trg_op\"><option value=\"GT\">&gt;</option><option value=\"LT\">&lt;</option><option value=\"GE\">&ge;</option><option value=\"LE\">&le;</option><option value=\"EQ\">=</option><option value=\"NE\">&ne;</option></select></div>'+\n"
"    '<div><label>Threshold</label><input name=\"trg_threshold\" type=\"number\" step=\"any\" value=\"30\" required></div></div>'+\n"
"    '<div><label style=\"margin-top:8px\"><input type=\"checkbox\" name=\"trg_checkbox\" checked> Activate trigger (uncheck to skip)</label></div>'+\n"
"    '<h2 style=\"margin-top:12px\">Action</h2>'+\n"
"    '<div class=\"form-row\"><div><label>Device ID</label><input name=\"act_dev\" value=\"dashboard\" required></div>'+\n"
"    '<div><label>Entity ID</label><input name=\"act_ent\" value=\"fan\" required></div></div>'+\n"
"    '<div class=\"form-row\"><div><label>Action Type</label><select name=\"act_type\"><option value=\"SET_BOOL\">Set Bool</option><option value=\"SET_LEVEL\">Set Level</option><option value=\"SET_VALUE\">Set Value</option><option value=\"TOGGLE\">Toggle</option></select></div>'+\n"
"    '<div><label>Value</label><input name=\"act_value\" type=\"number\" step=\"any\" value=\"1\"></div></div>'+\n"
"    '<div class=\"form-row\"><div><label>Cooldown (ms)</label><input name=\"cooldown_ms\" type=\"number\" value=\"60000\"></div>'+\n"
"    '<div><label>Priority</label><input name=\"priority\" type=\"number\" value=\"10\"></div></div>'+\n"
"    '<div><label>Max activations / hour</label><input name=\"max_act\" type=\"number\" value=\"10\"></div>'+\n"
"    '<button type=\"submit\" class=\"btn btn-primary\" style=\"margin-top:12px;width:100%\">Create</button>'+\n"
"    '<button type=\"button\" class=\"btn btn-ghost\" style=\"margin-top:8px;width:100%\" onclick=\"loadTab(\\'rules\\')\">Cancel</button>'+\n"
"    '</form></div>';\n"
"  document.getElementById('ruleForm').addEventListener('submit',function(e){\n"
"    e.preventDefault();\n"
"    var f=e.target.elements;\n"
"    var body={name:f.name.value};\n"
"    if(f.rule_id.value) body.rule_id=f.rule_id.value;\n"
"    if(f.trg_checkbox.checked){\n"
"      body.trigger={entity:{device_id:f.trg_dev.value,entity_id:f.trg_ent.value},operator:f.trg_op.value,threshold:parseFloat(f.trg_threshold.value)};\n"
"    }\n"
"    body.actions=[{entity:{device_id:f.act_dev.value,entity_id:f.act_ent.value},action:f.act_type.value,value:parseFloat(f.act_value.value)}];\n"
"    if(f.cooldown_ms.value) body.cooldown_ms=parseInt(f.cooldown_ms.value,10);\n"
"    if(f.priority.value) body.priority=parseInt(f.priority.value,10);\n"
"    if(f.max_act.value) body.max_activations_per_hour=parseInt(f.max_act.value,10);\n"
"    body.enabled=true;\n"
"    apiFetch('/rules',{method:'POST',body:JSON.stringify(body)})\n"
"      .then(function(){ loadTab('rules'); })\n"
"      .catch(renderError);\n"
"  });\n"
"};\n"
"\n"
"window.editRule=function(id){\n"
"  inFormView=true;\n"
"  apiFetch('/rules/'+encodeURIComponent(id)).then(function(rule){\n"
"    var trig=(rule.trigger&&rule.trigger.length)?rule.trigger[0]:null;\n"
"    var actions=rule.actions||[];\n"
"    var main=document.getElementById('mainContent');\n"
"    main.innerHTML='<div class=\"card\"><h2>Edit Rule: '+esc(rule.name)+'</h2><form id=\"ruleForm\">'+\n"
"      '<input type=\"hidden\" name=\"rule_id\" value=\"'+esc(rule.rule_id)+'\">'+\n"
"      '<div class=\"form-group\"><label>Name</label><input name=\"name\" value=\"'+esc(rule.name)+'\" required></div>'+\n"
"      '<div class=\"form-row\"><div><label>Priority</label><input name=\"priority\" type=\"number\" value=\"'+esc(rule.priority)+'\"></div>'+\n"
"      '<div><label>Cooldown (ms)</label><input name=\"cooldown_ms\" type=\"number\" value=\"'+esc(rule.cooldown_ms)+'\"></div></div>'+\n"
"      '<div><label>Max activations / hour</label><input name=\"max_act\" type=\"number\" value=\"'+esc(rule.max_activations_per_hour)+'\"></div>'+\n"
"      '<p class=\"entity-meta\" style=\"margin-top:8px\">Action: '+\n"
"        (actions[0]?(esc(actions[0].entity.device_id)+'/'+esc(actions[0].entity.entity_id)+' '+esc(actions[0].action)):'—')+\n"
"        ' | Trigger: '+(trig?esc(trig.entity.device_id)+'/'+esc(trig.entity.entity_id)+' '+esc(trig.operator)+' '+esc(trig.threshold):'—')+\n"
"        '</p>'+\n"
"      '<button type=\"submit\" class=\"btn btn-primary\" style=\"margin-top:12px;width:100%\">Update</button>'+\n"
"      '<button type=\"button\" class=\"btn btn-ghost\" style=\"margin-top:8px;width:100%\" onclick=\"loadTab(\\'rules\\')\">Cancel</button>'+\n"
"      '</form></div>';\n"
"    document.getElementById('ruleForm').addEventListener('submit',function(e){\n"
"      e.preventDefault();\n"
"      var f=e.target.elements;\n"
"      var body={name:f.name.value,priority:parseInt(f.priority.value,10),cooldown_ms:parseInt(f.cooldown_ms.value,10),max_activations_per_hour:parseInt(f.max_act.value,10)};\n"
"      if(trig) body.trigger=trig;\n"
"      if(actions.length) body.actions=actions;\n"
"      apiFetch('/rules/'+encodeURIComponent(id),{method:'PUT',body:JSON.stringify(body)})\n"
"        .then(function(){ loadTab('rules'); })\n"
"        .catch(renderError);\n"
"    });\n"
"  }).catch(renderError);\n"
"};\n"
"\n"
"window.toggleRule=function(id,enabled){\n"
"  apiFetch('/rules/'+encodeURIComponent(id)+(enabled?'/enable':'/disable'),{method:'POST'})\n"
"    .then(function(){ loadTab('rules'); })\n"
"    .catch(renderError);\n"
"};\n"
"window.deleteRule=function(id){\n"
"  if(!window.confirm('Delete rule '+id+'?')) return;\n"
"  apiFetch('/rules/'+encodeURIComponent(id),{method:'DELETE'})\n"
"    .then(function(){ loadTab('rules'); })\n"
"    .catch(renderError);\n"
"};\n"
"\n"
"document.querySelectorAll('.tab').forEach(function(b){\n"
"  b.addEventListener('click',function(){\n"
"    cur=b.dataset.tab;\n"
"    document.querySelectorAll('.tab').forEach(function(x){x.classList.toggle('active',x===b);});\n"
"    renderTab(cur);\n"
"  });\n"
"});\n"
"\n"
"window.addEventListener('unhandledrejection',function(e){ setOnline(false); });\n"
"\n"
"renderTab('dashboard');\n"
"setInterval(refreshVisible,10000);\n"
"</script>\n"
"</body>\n"
"</html>\n";
